#!/usr/bin/env bash
cat > /etc/nginx/conf.d/app.conf <<EOF
server {
  listen 80;
  location / {
    proxy_pass http://127.0.0.1:3000;
    proxy_set_header Host $host;
  }
}
EOF

import http from "node:http";
import { Pool } from "pg";

const pool = new Pool();
let draining = false;

const server = http.createServer((req, res) => {
  if (req.url === "/ready") {
    res.writeHead(draining ? 503 : 200).end();
    return;
  }
  res.end("ok");
});
server.listen(3000);

process.once("SIGTERM", () => {
  draining = true;                       // readiness fails from now on
  console.log("SIGTERM: draining");
  setTimeout(() => process.exit(1), 25_000).unref(); // hard stop < grace period

  server.close(async (err) => {          // stop accepting, wait for in-flight
    let failed = Boolean(err);
    try {
      await pool.end();                  // only after the last request is done
    } catch (e) {
      console.error("pool.end failed", e);
      failed = true;
    }
    process.exit(failed ? 1 : 0);
  });
});

process.on("SIGTERM", async () => {
  console.log("shutting down");
  await pool.end();
  server.close();
  process.exit(0);
});

